import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Alcance de armas y distancia","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/reach-and-spacing.md","filePath":"es/guide/combat/reach-and-spacing.md"}'),r={name:"es/guide/combat/reach-and-spacing.md"};function c(o,a,d,l,s,m){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="weapon-reach-and-spacing" tabindex="-1">Alcance de armas y distancia <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Enlace permanente a &quot;Alcance de armas y distancia&quot;">​</a></h1><p><strong>Estado:</strong> Experimental para distancias de tres armas · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>El alcance pertenece al arma/acción; la habilidad no la alarga de forma invisible.</li><li>La lanza Experimental amenaza más lejos, pero pierde eficacia de cerca.</li><li>Orientación, línea de visión y contacto legible siguen importando; Lunge no añade movimiento automático.</li></ul><p>La distancia forma parte del combate cuerpo a cuerpo. Una lanza puede amenazar más lejos, mientras su manejo de cerca deja espacio a un arma más corta.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arma/acción</th><th>Máximo</th><th>Mejor distancia / coste</th></tr></thead><tbody><tr><td>Longsword</td><td>1 casilla</td><td>Control cercano fiable</td></tr><tr><td>Spear Basic Thrust</td><td>2 casillas</td><td>Mejor a 2; desventaja a 1</td></tr><tr><td>Spear Lunge</td><td>3 casillas</td><td>Mejor a 2–3; compromiso costoso</td></tr><tr><td>War Hammer básica</td><td>1 casilla</td><td>Impacto cercano, recuperación lenta</td></tr><tr><td>Crushing Arc</td><td>2 casillas</td><td>Acción amplia visible; máximo 2 hostiles</td></tr><tr><td>Sweep</td><td>1 casilla</td><td>Arco corto; máximo 2 hostiles</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><ul><li>Las distancias de prueba usan una cuadrícula; línea de visión y orientación siguen importando.</li><li>Las estocadas de Spear y la respuesta de Brace a 1 casilla reciben −10 puntos porcentuales de precisión y ×0.85 al índice de daño.</li><li>El alcance es una propiedad física de la acción. La habilidad no alarga invisiblemente un arma.</li><li>Lunge extiende el golpe; esta prueba no incluye avance automático.</li><li>El alcance visible debe coincidir con el mecánico antes de poder implementar una acción.</li></ul><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Entrá en la distancia preferida de una lanza para presionar su manejo, o alejate mientras su portador se compromete con Lunge. Ninguna táctica garantiza un impacto.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/weapons-and-damage.html">Armas</a> · <a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Tablas de acciones</a> · <a href="/Syrolands-Public/es/game-design/combat/reach-and-spacing.html">Diseño completo</a></p>',13)])])}const h=e(r,[["render",c]]);export{u as __pageData,h as default};
